<script setup lang="ts">
import { ref, watch } from 'vue'
import Pagination from './Pagination.vue'
import { request, latestRequest } from '../api'
import { fmt, money, signed, timeText, orderStatuses } from '../format'
import type { Mutate, Page, Snapshot, Portfolio } from '../types'
interface Experiment {id:number|string;name:string;created_at?:string;start_date?:string;archived?:boolean;config?:{initial_cash:number;start_date:string};portfolio?:Portfolio;report?:{portfolio?:Portfolio;ledger?:Portfolio};ledger?:Portfolio}
const props=defineProps<{snapshot:Snapshot|null;active:boolean;enabled:boolean;mutate:Mutate}>()
const experiments=ref<Page<Experiment>>({items:[],total:0,page:1,pages:1,page_size:30}), busy=ref(false), error=ref(''), detail=ref<Experiment|null>(null)
const name=ref(''), initialCash=ref(100000), startDate=ref(''), confirmed=ref(false), saving=ref(false)
const generation=latestRequest()
watch(()=>props.snapshot?.app.demo_date,d=>{if(d&&!startDate.value)startDate.value=d},{immediate:true})
async function load(page=experiments.value.page){if(!props.active)return;const id=generation.next();busy.value=true;try{const result=await request<Page<Experiment>>(`/api/demo/experiments?page=${page}`);if(generation.current(id)){experiments.value=result;error.value=''}}catch(e){if(generation.current(id))error.value=e instanceof Error?e.message:String(e)}finally{if(generation.current(id))busy.value=false}}
watch(()=>[props.active,props.snapshot?.paper_experiment?.id],()=>{void load()},{immediate:true})
async function open(id:number|string){if(busy.value)return;busy.value=true;try{detail.value=await request<Experiment>(`/api/demo/experiments/${id}`);error.value=''}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function create(){if(!props.enabled||saving.value||!confirmed.value)return;if(!name.value.trim()||!Number.isFinite(initialCash.value)||initialCash.value<=0){error.value='请填写实验名称和正数初始资金。';return}saving.value=true;try{if(await props.mutate('/api/demo/experiments',{name:name.value.trim(),initial_cash:initialCash.value,start_date:startDate.value},'旧模拟实验已归档，新实验已创建。')){name.value='';confirmed.value=false;detail.value=null;await load()}}finally{saving.value=false}}
const ledger=(e:Experiment)=>e.portfolio??e.report?.portfolio??e.report?.ledger??e.ledger
</script>
<template>
<section class="panel block-panel"><div class="panel-heading"><div><h2>模拟实验管理</h2><p>当前：{{ snapshot?.paper_experiment?.name || '初始演示实验' }} · 新建时保留并归档现有资金、持仓及记录</p></div></div><div class="experiment-grid"><form @submit.prevent="create"><fieldset :disabled="!enabled||saving"><div class="form-row"><label>新实验名称<input v-model="name" maxlength="60" placeholder="例如：十万元规则验证" required></label><label>初始资金（元）<input v-model.number="initialCash" type="number" min="100" max="100000000" step=".01" required></label></div><label>起始演示日期<input v-model="startDate" type="date" min="2025-01-02" max="2026-12-31" required></label><label class="checkbox-label"><input v-model="confirmed" type="checkbox">归档当前实验，使用独立的新账本</label><button class="button secondary" :disabled="!confirmed" type="submit">{{ saving?'正在创建…':'归档并新建实验' }}</button></fieldset></form><div><div v-if="error" class="error-banner">{{ error }}</div><div class="table-wrap"><table><thead><tr><th>实验</th><th>日期</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="item in experiments.items" :key="item.id"><td>{{ item.name }}</td><td>{{ timeText(item.created_at) }}</td><td>{{ item.archived?'已归档':'当前' }}</td><td><button class="cancel-order" :disabled="busy" @click="open(item.id)">查看账本</button></td></tr><tr v-if="!experiments.items.length"><td colspan="4" class="empty">尚无归档实验。</td></tr></tbody></table></div><div class="panel-footer"><span>共 {{ experiments.total }} 项</span><Pagination :page="experiments.page" :pages="experiments.pages" :busy="busy" label="演示实验分页" @change="load"/></div></div></div>
<div v-if="detail" class="experiment-detail"><div class="summary-label"><h2>{{ detail.name }} · {{ detail.archived?'归档账本':'当前账本' }}</h2><button class="cancel-order" @click="detail=null">收起</button></div><template v-if="ledger(detail)"><div class="report-metrics"><span>初始 {{ money(ledger(detail)?.initial_cash) }}</span><span>总资产 {{ money(ledger(detail)?.equity) }}</span><span>已实现 {{ signed(ledger(detail)?.realized_pnl) }}</span><span>费用 {{ money(ledger(detail)?.fees) }}</span></div><h3>持仓</h3><div class="table-wrap"><table><thead><tr><th>代码</th><th>数量</th><th>成本</th><th>浮动收益</th></tr></thead><tbody><tr v-for="p in ledger(detail)?.positions??[]" :key="p.code"><td>{{ p.code }}</td><td>{{ fmt(p.quantity,0) }}</td><td>{{ money(p.avg_cost) }}</td><td>{{ signed(p.unrealized_pnl) }}</td></tr></tbody></table></div><details><summary>全部委托（{{ ledger(detail)?.orders?.length??0 }}）</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>股票</th><th>方向</th><th class="num">股数</th><th>状态</th><th>说明</th></tr></thead><tbody><tr v-for="o in ledger(detail)?.orders??[]" :key="o.id"><td>{{ o.created_date }}</td><td>{{ o.code }}</td><td>{{ o.side==='buy'?'买入':'卖出' }}</td><td class="num">{{ fmt(o.quantity,0) }}</td><td>{{ orderStatuses[o.status]??o.status }}</td><td class="order-note">{{ o.reason||'—' }}</td></tr><tr v-if="!ledger(detail)?.orders?.length"><td colspan="6" class="empty">没有委托记录。</td></tr></tbody></table></div></details><details><summary>全部成交（{{ ledger(detail)?.trades?.length??0 }}）</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>股票</th><th>方向</th><th>股数</th><th>价格</th><th>费用</th><th>已实现收益</th></tr></thead><tbody><tr v-for="(t,i) in ledger(detail)?.trades??[]" :key="i"><td>{{ t.date }}</td><td>{{ t.code }}</td><td>{{ t.side==='buy'?'买':'卖' }}</td><td>{{ fmt(t.quantity,0) }}</td><td>{{ money(t.price) }}</td><td>{{ money(t.fee) }}</td><td>{{ signed(t.pnl) }}</td></tr></tbody></table></div></details></template><p v-else class="form-help">此实验尚无可显示的归档账本。</p></div></section>
</template>
